From f63a904c000531ddb3fbcff952b79ef21c2f7901 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:16:48 +0100
Subject: [PATCH] containmentlayoutmanager: block applet input in edit mode
 without disabling it

Desktop widgets were disabled while their edit mode handles were shown,
so they switched to the grey disabled text color. Cover them with an
input blocker instead, which hands left presses to the container.

BUG: 512468
---
 .../itemcontainer.cpp                         | 54 +++++++++++++++++--
 .../containmentlayoutmanager/itemcontainer.h  |  3 ++
 2 files changed, 52 insertions(+), 5 deletions(-)

diff --git a/components/containmentlayoutmanager/itemcontainer.cpp b/components/containmentlayoutmanager/itemcontainer.cpp
index e23678ef37..a16a1c820c 100644
--- a/components/containmentlayoutmanager/itemcontainer.cpp
+++ b/components/containmentlayoutmanager/itemcontainer.cpp
@@ -21,6 +21,45 @@

 using namespace std::chrono_literals;

+// Covers the applet while its edit mode handles are shown, so it gets no input
+// without being disabled, which would give it the disabled colors
+class ContentInputBlocker : public QQuickItem
+{
+public:
+    explicit ContentInputBlocker(ItemContainer *container)
+        : QQuickItem(container)
+        , m_container(container)
+    {
+        setAcceptedMouseButtons(Qt::LeftButton);
+        setAcceptHoverEvents(true);
+    }
+
+protected:
+    void mousePressEvent(QMouseEvent *event) override
+    {
+        m_container->mousePressEvent(event);
+    }
+    void mouseMoveEvent(QMouseEvent *event) override
+    {
+        m_container->mouseMoveEvent(event);
+    }
+    void mouseReleaseEvent(QMouseEvent *event) override
+    {
+        m_container->mouseReleaseEvent(event);
+    }
+    void mouseDoubleClickEvent(QMouseEvent *event) override
+    {
+        event->accept();
+    }
+    void wheelEvent(QWheelEvent *event) override
+    {
+        event->accept();
+    }
+
+private:
+    ItemContainer *const m_container;
+};
+
 ItemContainer::ItemContainer(QQuickItem *parent)
     : QQuickItem(parent)
 {
@@ -59,10 +98,6 @@ ItemContainer::ItemContainer(QQuickItem *parent)
 ItemContainer::~ItemContainer()
 {
     disconnect(this, &QQuickItem::parentChanged, this, nullptr);
-
-    if (m_contentItem) {
-        m_contentItem->setEnabled(true);
-    }
 }

 QString ItemContainer::key() const
@@ -118,7 +153,12 @@ void ItemContainer::setEditMode(bool editMode)
     m_editMode = editMode;

     if (m_contentItem && (m_editModeCondition != AfterMouseOver || (m_layout && m_layout->editMode()))) {
-        m_contentItem->setEnabled(!editMode);
+        if (!m_contentInputBlocker) {
+            m_contentInputBlocker = new ContentInputBlocker(this);
+            m_contentInputBlocker->setZ(998);
+            m_contentInputBlocker->setSize(size());
+        }
+        m_contentInputBlocker->setVisible(editMode);
     }

     if (editMode) {
@@ -285,6 +325,10 @@ void ItemContainer::syncChildItemsGeometry(const QSizeF &size)
         m_backgroundItem->setSize(size);
     }

+    if (m_contentInputBlocker) {
+        m_contentInputBlocker->setSize(size);
+    }
+
     if (m_configOverlay) {
         m_configOverlay->setPosition(QPointF(0, 0));
         m_configOverlay->setSize(size);
diff --git a/components/containmentlayoutmanager/itemcontainer.h b/components/containmentlayoutmanager/itemcontainer.h
index 2aecb2c72b..b204effc6e 100644
--- a/components/containmentlayoutmanager/itemcontainer.h
+++ b/components/containmentlayoutmanager/itemcontainer.h
@@ -15,6 +15,7 @@
 class QTimer;

 class ConfigOverlay;
+class ContentInputBlocker;

 class ItemContainer : public QQuickItem
 {
@@ -194,6 +195,7 @@ private Q_SLOTS:

 private:
     friend class AppletsLayout;
+    friend class ContentInputBlocker;
     void syncChildItemsGeometry(const QSizeF &size);
     void sendUngrabRecursive(QQuickItem *item);

@@ -207,6 +209,7 @@ private:

     QPointer<QQuickItem> m_contentItem;
     QPointer<QQuickItem> m_backgroundItem;
+    QQuickItem *m_contentInputBlocker = nullptr;

     // Internal implementation detail: this is used to reparent all items to contentItem
     QList<QObject *> m_contentData;
